def process_http_request(data: bytes) -> dict:
    max_length = 8192
    if len(data) > max_length:
        raise ValueError('Buffer overflow detected')

    headers = data.decode('utf-8').split('\r\n')
    header_dict = {}

    for header in headers:
        if ':' not in header:
            raise ValueError('Malformed HTTP header')

        key, value = header.split(':', 1)
        header_dict[key.strip()] = value.strip()

    for required_header in required_headers:
        if required_header not in header_dict:
            raise ValueError(f'Required header {required_header} is missing')

    return header_dict
